//! The two `Perform` bodies of `LocOpe_DPrism`
//! (`LocOpe_DPrism.cxx:112-359` and `:391-551`).
//!
//! Both follow the same four stages:
//!
//! 1. `myFirstShape` from the faces generated by `myProfile1` (`cxx:113-181`,
//!    `cxx:392-459`).
//! 2. `myLastShape` from the faces generated by `myProfile3` (`cxx:183-240`,
//!    `cxx:462-519`).
//! 3. the middle pass over `myProfile2` (`cxx:242-354`, `cxx:521-547`): the
//!    two-heights ctor rebuilds every face that carries the "removed" middle
//!    edge on its plane without that edge (`cxx:255-320`), the single-height
//!    one only collects the descendants.
//! 4. `LocOpe_BuildShape` over the accumulated faces and
//!    `BRepLib::UpdateTolerances` (`cxx:356-359`, `cxx:549-551`).
//!
//! Stages 1 and 2 are the same block twice; they share [`end_cap`], which also
//! answers the faces the reference appends to `lcomplete` (`cxx:165-166`).

use crate::abs::{Orientation, ShapeType};
use crate::brep_fill_evolved::BRepFillEvolved;
use crate::brep_lib_update_tolerances::update_tolerances;
use crate::brep_tool::BRepTool;
use crate::builder::TopoBuilder;
use crate::locope::build_shape::BuildShape;
use crate::locope::shape_maps::ShapeSet;
use crate::locope::dprism::DPrism;
use crate::shape::{Edge, Face, TopoShape, Wire};
use crate::shape_fix_compose_shell::empty_copied_face;
use crate::topo_tools::{edges_of_wire, explorer_shapes, is_same, wires_of_face, AncestorMap};

/// `myFirstShape` / `myLastShape` block (`cxx:113-181` for the first cap,
/// `cxx:183-240` for the last: identical apart from the compound).
///
/// The faces generated from the spine edges by `prof` are collected in a
/// compound; every face touching an edge that only one face of that compound
/// uses is rebuilt as a copy carrying just the wire that holds this edge
/// (`cxx:150-176`); `LocOpe_BuildShape` then assembles the rebuilt faces.
///
/// The returned `Vec` is the `lfaces` list, which the reference also appends to
/// `lcomplete` (`cxx:165-166`) - i.e. the cap faces are part of the final
/// assembly as well.
fn end_cap(
    dprism: &BRepFillEvolved,
    spine: &Face,
    prof: &Edge,
) -> (Option<TopoShape>, Vec<TopoShape>) {
    let b = TopoBuilder::new();

    // `cxx:120-135`: the compound of every distinct generated shape.
    let mut view = ShapeSet::new();
    let mut collected: Vec<TopoShape> = Vec::new();
    for es in explorer_shapes(&spine.0, ShapeType::Edge) {
        for s in dprism.generated_shapes(&es, &prof.0) {
            if view.add(&s) {
                collected.push(s);
            }
        }
    }
    let compound = b.make_compound_of(&collected);

    // `cxx:138-141`.
    let the_map_ef =
        AncestorMap::map_shapes_and_ancestors(&compound.0, ShapeType::Edge, ShapeType::Face);
    view.clear();

    // `cxx:145-177`.
    let mut lfaces: Vec<TopoShape> = Vec::new();
    for i in 0..the_map_ef.length() {
        let ancestors = the_map_ef.ancestors(i);
        // `theMapEF(i).Extent() == 1`.
        if ancestors.len() != 1 {
            continue;
        }
        let edg = the_map_ef.find_key(i).clone();
        let fac = ancestors[0].clone();
        if !view.add(&fac) {
            continue;
        }
        // `fac.EmptyCopied()` (`cxx:151`): surface, location and tolerance.
        let mut new_face = Face(empty_copied_face(&fac));
        let forward = Face(fac.oriented(Orientation::Forward));
        for w in wires_of_face(&forward) {
            let mut found = false;
            for e in edges_of_wire(&w) {
                if is_same(&e.0, &edg) {
                    // `B.Add(newFace, exp.Current())`: the wire keeps its
                    // orientation.
                    b.add_wire(&mut new_face, &w);
                    lfaces.push(new_face.0.clone());
                    found = true;
                    break;
                }
            }
            if found {
                break;
            }
        }
    }

    // `cxx:179-180`.
    let mut bs = BuildShape::new();
    let _ = bs.perform(&lfaces);
    (bs.shape().cloned(), lfaces)
}

/// `LocOpe_DPrism(Spine, Height1, Height2, Angle)` body (`cxx:112-359`).
pub(super) fn perform_dual(m: &mut DPrism) {
    let spine = m.my_spine.clone();
    let (Some(profile1), Some(profile2), Some(profile3)) =
        (m.my_profile1.clone(), m.my_profile2.clone(), m.my_profile3.clone())
    else {
        return;
    };

    // Stage 1 (`cxx:113-181`).
    let (first, faces1) = end_cap(&m.my_dprism, &spine, &profile1);
    m.my_first_shape = first;
    // Stage 2 (`cxx:183-240`).
    let (last, faces2) = end_cap(&m.my_dprism, &spine, &profile3);
    m.my_last_shape = last;

    let b = TopoBuilder::new();
    let mut lcomplete: Vec<TopoShape> = Vec::new();
    lcomplete.extend(faces1);
    lcomplete.extend(faces2);

    // `cxx:242`: `View.Clear()`, then stage 3.
    let mut view = ShapeSet::new();
    for es in explorer_shapes(&spine.0, ShapeType::Edge) {
        let lffs = m.my_dprism.generated_shapes(&es, &profile2.0);

        // `cxx:248-257`: the first generated edge is the one to remove; when
        // the list has none, the reference falls to the `else` arm.
        let removed = lffs
            .iter()
            .find(|s| s.shape_type() == ShapeType::Edge)
            .cloned();

        if let Some(removed) = removed {
            // `cxx:259-311`: rebuild the planar faces without `removed`.
            let mut new_face: Option<Face> = None;
            let mut new_wire = Wire::new();
            let mut orref = Orientation::Forward;
            for s in &lffs {
                if s.shape_type() != ShapeType::Face {
                    continue;
                }
                let fac = Face(s.oriented(Orientation::Forward));
                // `exp.Init(it.Value().Oriented(FORWARD), TopAbs_WIRE)`.
                let the_wire = wires_of_face(&fac).into_iter().next().unwrap_or_else(Wire::new);
                if new_face.is_none() {
                    // `cxx:270-279`: the face must be planar. `None` here is the
                    // null `BRep_Tool::Surface`, which the reference would
                    // de-reference.
                    let Some(surface) = BRepTool::face_surface(&fac) else {
                        break;
                    };
                    let surface = surface.rectangular_trimmed_basis().unwrap_or(surface);
                    if surface.gp_pln().is_none() {
                        break;
                    }
                    let tol = BRepTool::face_tolerance(&fac);
                    // `B.MakeFace(NewFace, S, tol)` + `NewFace.Orientation(FORWARD)`.
                    let mut nf = b.make_face_with_tolerance(surface, &[], tol);
                    nf.0.set_orientation(Orientation::Forward);
                    orref = the_wire.0.orientation();
                    for e in edges_of_wire(&Wire(the_wire.0.oriented(Orientation::Forward))) {
                        if !is_same(&e.0, &removed) {
                            b.add_edge(&mut new_wire, &e);
                        }
                    }
                    new_face = Some(nf);
                } else {
                    for e in edges_of_wire(&Wire(the_wire.0.oriented(Orientation::Forward))) {
                        if is_same(&e.0, &removed) {
                            continue;
                        }
                        if the_wire.0.orientation() != orref {
                            // The two planar faces have opposite normals.
                            b.add_edge(&mut new_wire, &e);
                        } else {
                            let mut r = e.0.clone();
                            r.reverse();
                            b.add_edge(&mut new_wire, &Edge(r));
                        }
                    }
                }
            }

            // `cxx:313-330`.
            if let Some(mut nf) = new_face {
                let oriented = Wire(new_wire.0.oriented(orref));
                b.add_wire(&mut nf, &oriented);
                lcomplete.push(nf.0.clone());
                // `myMap.Bind(ES, thelist); myMap(ES).Append(NewFace)`.
                m.my_map.bind(&es, vec![nf.0.clone()]);
            } else {
                for s in &lffs {
                    if view.add(s) && s.shape_type() == ShapeType::Face {
                        lcomplete.push(s.clone());
                    }
                }
            }
        } else {
            // `cxx:331-341`.
            for s in &lffs {
                if view.add(s) && s.shape_type() == ShapeType::Face {
                    lcomplete.push(s.clone());
                }
            }
        }

        // `cxx:343-353`.
        for vtx in explorer_shapes(&es, ShapeType::Vertex) {
            for s in m.my_dprism.generated_shapes(&vtx, &profile2.0) {
                if view.add(&s) && s.shape_type() == ShapeType::Face {
                    lcomplete.push(s);
                }
            }
        }
    }

    // `cxx:356-359`.
    finish(m, &lcomplete);
}

/// `LocOpe_DPrism(Spine, Height, Angle)` body (`cxx:391-551`).
pub(super) fn perform_single(m: &mut DPrism) {
    let spine = m.my_spine.clone();
    let (Some(profile1), Some(profile2), Some(profile3)) =
        (m.my_profile1.clone(), m.my_profile2.clone(), m.my_profile3.clone())
    else {
        return;
    };

    // Stage 1 (`cxx:392-459`).
    let (first, faces1) = end_cap(&m.my_dprism, &spine, &profile1);
    m.my_first_shape = first;
    // Stage 2 (`cxx:462-519`).
    let (last, faces2) = end_cap(&m.my_dprism, &spine, &profile3);
    m.my_last_shape = last;

    let mut lcomplete: Vec<TopoShape> = Vec::new();
    lcomplete.extend(faces1);
    lcomplete.extend(faces2);

    // `cxx:521-547`: unlike the two-heights ctor this pass appends every
    // generated shape of the spine edge, not only the faces (`cxx:529-531`).
    let mut view = ShapeSet::new();
    for es in explorer_shapes(&spine.0, ShapeType::Edge) {
        for s in m.my_dprism.generated_shapes(&es, &profile2.0) {
            if view.add(&s) {
                lcomplete.push(s);
            }
        }
        for vtx in explorer_shapes(&es, ShapeType::Vertex) {
            for s in m.my_dprism.generated_shapes(&vtx, &profile2.0) {
                if view.add(&s) && s.shape_type() == ShapeType::Face {
                    lcomplete.push(s);
                }
            }
        }
    }

    // `cxx:549-551`.
    finish(m, &lcomplete);
}

/// `LocOpe_BuildShape` + `BRepLib::UpdateTolerances` tail shared by both
/// constructors (`cxx:356-359`, `cxx:549-551`).
fn finish(m: &mut DPrism, lcomplete: &[TopoShape]) {
    let mut bs = BuildShape::new();
    let _ = bs.perform(lcomplete);
    let res = bs.shape().cloned();
    if let Some(shape) = &res {
        // `BRepLib::UpdateTolerances(verifyFaceTolerance = false)`.
        let _ = update_tolerances(shape, false);
    }
    m.my_res = res;
}
